from agent import *from models.products import *import simplejsonXCAT = ['Certified Pre-Owned']def run(context: dict[str, str], session: Session):    session.queue(Request('https://www.theaudiotailor.com.au/', use='curl', force_charset='utf-8'), process_frontpage, {})def process_frontpage(data: Response, context: dict[str, str], session: Session):    cats1 = data.xpath('//li[contains(@class, "category")]/ul/li')    for cat1 in cats1:        name1 = cat1.xpath('a/text()').string()        if name1 not in XCAT:            cats2 = cat1.xpath('ul/li/a')            for cat2 in cats2:                name2 = cat2.xpath('text()').string()                url = cat2.xpath("@href").string()                session.queue(Request(url, use='curl', force_charset='utf-8'), process_prodlist, dict(cat=name1+'|'+name2))def process_prodlist(data: Response, context: dict[str, str], session: Session):    prods = data.xpath('//div[@class="productitem--info"]')    for prod in prods:        name = prod.xpath('h2/a/text()').string()        prod_id = prod.xpath('h2/a/@href').string().split('/')[-1]        url = 'https://www.theaudiotailor.com.au/products/' + prod_id        manufacturer = prod.xpath('span[@class="productitem--vendor"]/a/text()').string()        revs_cnt = prod.xpath('.//p[@class="rating__count"]/span/text()').string()        if revs_cnt:            revs_cnt = int(revs_cnt.split()[0])            if revs_cnt > 0:                session.queue(Request(url, use='curl', force_charset='utf-8'), process_product, dict(context, name=name, url=url, manufacturer=manufacturer))    next_url = data.xpath('//link[@rel="next"]/@href').string()    if next_url:        session.queue(Request(next_url, use='curl', force_charset='utf-8'), process_prodlist, dict(context))def process_product(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['name']    product.url = context['url']    product.manufacturer = context['manufacturer']    product.category = context['cat']    product.ssid = data.xpath('//div/@data-id').string()    prod_json = data.xpath("""//script[contains(., '"@type": "Product"')]/text()""").string()    if prod_json:        prod_json = simplejson.loads(prod_json)        mpn = prod_json.get('sku')        if mpn:            product.properties.append(ProductProperty(type='id.manufacturer', value=mpn))        ean = prod_json.get('mpn')        if ean:            product.properties.append(ProductProperty(type='id.ean', value=str(ean)))    reviews_url = 'https://productreviews.shopifycdn.com/proxy/v4/reviews?callback=paginateCallback{pid}&page=1&product_id={pid}&shop=aussie-hi-fi.myshopify.com'.format(pid=product.ssid)    session.do(Request(reviews_url, use='curl', force_charset='utf-8', max_age=0), process_reviews, dict(context, product=product))    if product.reviews:        session.emit(product)def process_reviews(data: Response, context: dict[str, str], session: Session):    product = context['product']    html_content = data.content.split(product.ssid, 1)[-1].strip('()')    json = simplejson.loads(html_content)    resp = json.get('reviews')    revs_html = data.parse_fragment(resp)    revs = revs_html.xpath('//div[@class="spr-review"]')    for rev in revs:        review = Review()        review.url = product.url        review.title = rev.xpath('.//h3[@class="spr-review-header-title"]/text()').string()        review.type = "user"        review.ssid = rev.xpath('@id').string().split('-')[-1]        author = rev.xpath('.//strong[@class="author"]/text()').string()        if author:            review.authors.append(Person(name=author, ssid=author))        is_verified = rev.xpath('.//span[@class="verified"]')        if is_verified:            review.add_property(type='is_verified_buyer', value=True)        date = rev.xpath('.//span[@class="spr-review-header-byline"]//text()').string(multiple=True)        if date:            review.date = date.split(' on ')[-1]        grade_overall = rev.xpath('.//span[@class="spr-starratings spr-review-header-starratings"]/@aria-label').string()        if grade_overall:            value = grade_overall.split('of ')[0]            review.grades.append(Grade(type="overall", value=float(value), best=5.0))        excerpt = rev.xpath('.//p[@class="spr-review-content-body"]/text()').string(multiple=True)        if excerpt:            review.properties.append(ReviewProperty(type="excerpt", value=excerpt))            product.reviews.append(review)    next_url = revs_html.xpath('.//span[@class="spr-pagination-next"]').string()    if next_url:        next_page = context.get('page', 1) + 1        next_url = 'https://productreviews.shopifycdn.com/proxy/v4/reviews?callback=paginateCallback{pid}&page={}&product_id={pid}&shop=aussie-hi-fi.myshopify.com'.format(next_page, pid=product.ssid)        session.do(Request(next_url, use='curl', force_charset='utf-8', max_age=0), process_reviews, dict(context, product=product, page=next_page))